import {CodescanIcon, PackageIcon, TagIcon, ToolsIcon, KeyIcon} from '@primer/octicons-react'
import {AsyncSuggestionsFilterProvider} from '@github-ui/code-scanning-shared/filter-providers/async-suggestions-filter-provider'
import type {FilterKey} from '@github-ui/filter'
import {ssrSafeLocation} from '@github-ui/ssr-utils'

export class RuleFilterProvider extends AsyncSuggestionsFilterProvider {
  constructor({path}: {path: string}) {
    super(
      {
        displayName: 'Rule',
        key: 'rule',
        priority: 1,
        icon: CodescanIcon,
        description: 'Find alerts from the selected rule',
      } as FilterKey,
      path,
    )
  }
}

