export class SecretTypeFilterProvider extends AsyncSuggestionsFilterProvider {
  constructor({path}: {path: string}) {
    super(
      {
        displayName: 'Secret type',
        key: 'secret-type',
        priority: 1,
        icon: KeyIcon,
        description: 'Find secret scanning alerts with the selected secret type',
        aliases: ['secret-scanning.secret-type'],
      } as FilterKey,
      getSuggestionsPath({path, type: 'secret-scanning.secret-types'}),
    )
  }
}

