export class ArtifactRegistryURLFilterProvider extends AsyncSuggestionsFilterProvider {
  constructor({path}: {path: string}) {
    super(
      {
        displayName: 'Artifact registry URL',
        key: 'artifact-registry-url',
        priority: 1,
        icon: PackageIcon,
        description: `Finds alerts detected in repositories with artifacts published to the selected artifact registry URL`,
      } as FilterKey,
      getSuggestionsPath({path, type: 'dependabot.artifact-registry-urls'}),
    )
  }
}

export function getSuggestionsPath(
  {path, type}: {path: string; type: string},
  additionalParams: Record<string, string> = {},
): string {
  const url = new URL(path, ssrSafeLocation.origin)
  url.searchParams.set('options-type', type)
  for (const [key, value] of Object.entries(additionalParams)) {
    url.searchParams.set(key, value)
  }
  return url.toString()
}
