import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'

export function useDeleteSecurityCampaignMutation(path: string): UseMutationResult<void, Error, void> {
  return useMutation({
    mutationFn: () => {
      return fetchJson(path, {
        method: 'delete',
        defaultErrorMessage: 'Error deleting security campaign',
      })
    },
  })
}
