import {useMemo} from 'react'
import {
  AutofilterFilterProvider,
  AutofixFilterProvider,
  CampaignFilterProvider,
  ResolutionFilterProvider,
  SeverityFilterProvider,
  SortFilterProvider,
  StateFilterProvider,
  SecretValidityFilterProvider,
  SecretBypassedFilterProvider,
  SecretScanningStateFilterProvider,
  SecretScanningResolutionFilterProvider,
  ArtifactRegistryFilterProvider,
  ResultsFilterProvider,
  RuntimeRiskFilterProvider,
  HasDeploymentFilterProvider,
} from '../filter-providers/StaticProviders'
import {
  RuleFilterProvider,
  ToolFilterProvider,
  TagFilterProvider,
  SecretTypeFilterProvider,
  SecretProviderFilterProvider,
  ArtifactRegistryURLFilterProvider,
  getSuggestionsPath,
} from '../filter-providers/DynamicProviders'
import {
  CustomPropertyFilterProvider,
  RepositoryFilterProvider,
  TeamFilterProvider,
  TopicFilterProvider,
} from '@github-ui/code-scanning-shared/filter-providers/repository-filter-providers'
import {
  codeScanningOrgRepositoryListPath,
  codeScanningOrgRuleListPath,
  codeScanningOrgTagListPath,
  codeScanningOrgToolListPath,
  getRelativeHref,
  secretScanningOrgRepositoryListPath,
  securityCenterOptionsPath,
} from '@github-ui/paths'
import {AssigneeFilterProvider} from '@github-ui/filter-core/providers'
import type {FilterProvider} from '@github-ui/filter'
import type {AlertType} from '../types/security-campaign-alert'
import {isEnterprise} from '@github-ui/runtime-environment'

type UseFilterProvidersOptions = {
  organizationLogin: string
  showSort: boolean
  showNewAutofixFilters: boolean
  showCampaignFilter: boolean
  customPropertyNames: string[]
  securityCampaignNumber?: number
  securityCampaignPublished?: boolean
  alertType?: AlertType
}

export function useAlertFilterProviders({
  organizationLogin,
  showSort,
  showNewAutofixFilters,
  showCampaignFilter,
  customPropertyNames,
  securityCampaignNumber,
  securityCampaignPublished = false,
  alertType,
}: UseFilterProvidersOptions) {
  const filterProviders = useMemo(() => {
    const suggestionsPath = securityCenterOptionsPath({
      org: organizationLogin,
    })

    if (alertType === 'secret_scanning') {
      const providers: FilterProvider[] = [
        new RepositoryFilterProvider({
          path: getRelativeHref(
            secretScanningOrgRepositoryListPath,
            {org: organizationLogin},
            {
              security_campaign_number: securityCampaignNumber,
            },
          ).toString(),
        }),
        new SecretScanningStateFilterProvider(),
        new SecretScanningResolutionFilterProvider(),
        new SecretBypassedFilterProvider(),
        new SecretValidityFilterProvider(),
        new SecretTypeFilterProvider({path: suggestionsPath}),
        new SecretProviderFilterProvider({path: suggestionsPath}),
        new AssigneeFilterProvider({
          showAtMe: true,
        }),
      ]

      if (!securityCampaignPublished) {
        // only needed when creating a campaign or editing a draft, unavailable for published campaigns
        providers.push(new ResultsFilterProvider())
      }

      if (showSort) providers.push(new SortFilterProvider())
      if (showCampaignFilter) providers.push(new CampaignFilterProvider())
      providers.push(
        ...customPropertyNames.map(
          name => new CustomPropertyFilterProvider({customPropertyName: name, path: suggestionsPath}),
        ),
      )

      return providers
    }

    // Default to code scanning providers if alertType is not 'secret_scanning'
    // Order determines the position of the filter in suggestion list.
    const providers: FilterProvider[] = [
      new RepositoryFilterProvider({
        path: getRelativeHref(
          codeScanningOrgRepositoryListPath,
          {org: organizationLogin},
          {
            security_campaign_number: securityCampaignNumber,
          },
        ).toString(),
      }),
      new ResolutionFilterProvider(),
      new RuleFilterProvider({
        path: getRelativeHref(
          codeScanningOrgRuleListPath,
          {org: organizationLogin},
          {
            security_campaign_number: securityCampaignNumber,
          },
        ).toString(),
      }),
      new TagFilterProvider({
        path: getRelativeHref(
          codeScanningOrgTagListPath,
          {org: organizationLogin},
          {
            security_campaign_number: securityCampaignNumber,
          },
        ).toString(),
      }),
      new SeverityFilterProvider(),
      ...(showSort ? [new SortFilterProvider()] : []),
      new StateFilterProvider(),
      new TeamFilterProvider({path: getSuggestionsPath({path: suggestionsPath, type: 'teams'})}),
      new ToolFilterProvider({
        path: getRelativeHref(
          codeScanningOrgToolListPath,
          {org: organizationLogin},
          {
            security_campaign_number: securityCampaignNumber,
          },
        ).toString(),
      }),
      new TopicFilterProvider({path: getSuggestionsPath({path: suggestionsPath, type: 'topics'})}),
      new AutofilterFilterProvider(),
      new AutofixFilterProvider(showNewAutofixFilters),
      new AssigneeFilterProvider({
        showAtMe: true,
        showAtCopilot: true,
      }),
      ...customPropertyNames.map(
        name =>
          new CustomPropertyFilterProvider({
            customPropertyName: name,
            path: getSuggestionsPath({path: suggestionsPath, type: 'props'}, {name}),
          }),
      ),
    ]

    if (!isEnterprise()) {
      providers.push(new ArtifactRegistryFilterProvider())
      providers.push(new ArtifactRegistryURLFilterProvider({path: suggestionsPath}))
      providers.push(new RuntimeRiskFilterProvider())
      providers.push(new HasDeploymentFilterProvider())
    }

    if (showCampaignFilter) {
      providers.push(new CampaignFilterProvider())
    }

    return providers
  }, [
    organizationLogin,
    showSort,
    showNewAutofixFilters,
    customPropertyNames,
    securityCampaignNumber,
    securityCampaignPublished,
    showCampaignFilter,
    alertType,
  ])

  return filterProviders
}
