import {useState} from 'react'
import {AnchoredOverlay, Button} from '@primer/react'

import {IssueOpenedIcon} from '@primer/octicons-react'
import {issuePath} from '@github-ui/paths'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'

import {AlertTrackingLinksOverlayContent} from './AlertTrackingLinksOverlayContent'
import styles from './AlertTrackingLinksButton.module.css'
import {TrackingSystem, type TrackingLink} from '@github-ui/code-scanning-shared/types/tracking-link'

export type AlertTrackingLinksButtonProps = {
  trackingLinks: TrackingLink[]
}

function getTrackingLinkUrl(trackingLink: TrackingLink): string | undefined {
  if (trackingLink.trackingSystem === TrackingSystem.GITHUB_ISSUE && trackingLink.issue) {
    return issuePath({
      owner: trackingLink.issue.repository.ownerLogin,
      repo: trackingLink.issue.repository.name,
      issueNumber: trackingLink.issue.number,
    })
  }
  return trackingLink.trackingUrl ?? undefined
}

export function AlertTrackingLinksButton({trackingLinks}: AlertTrackingLinksButtonProps) {
  const [open, setOpen] = useState(false)
  const getHovercardAttributesForType = useGetHovercardAttributesForType()

  const leadingVisual = <IssueOpenedIcon fill="var(--fgColor-muted)" />

  if (trackingLinks.length === 0) {
    return null
  }

  if (trackingLinks.length === 1 && trackingLinks[0]) {
    const trackingLink = trackingLinks[0]
    const href = getTrackingLinkUrl(trackingLink)

    if (!href) {
      return null
    }

    if (trackingLink.trackingSystem === TrackingSystem.GITHUB_ISSUE && trackingLink.issue) {
      return (
        <Button
          as="a"
          href={href}
          variant="invisible"
          leadingVisual={leadingVisual}
          {...getHovercardAttributesForType('issue', {
            owner: trackingLink.issue.repository.ownerLogin,
            repo: trackingLink.issue.repository.name,
            issueNumber: trackingLink.issue.number,
          })}
        >
          {trackingLinks.length}
        </Button>
      )
    }

    return (
      <Button as="a" href={href} variant="invisible" leadingVisual={leadingVisual}>
        {trackingLinks.length}
      </Button>
    )
  }

  return (
    <AnchoredOverlay
      open={open}
      onOpen={() => setOpen(true)}
      onClose={() => setOpen(false)}
      renderAnchor={props => (
        <Button variant="invisible" leadingVisual={leadingVisual} {...props}>
          {trackingLinks.length}
        </Button>
      )}
    >
      <div className={`width-full height-full ${styles.overlayContainer}`}>
        <AlertTrackingLinksOverlayContent trackingLinks={trackingLinks} />
      </div>
    </AnchoredOverlay>
  )
}
