import {ActionList, ActionMenu, Tooltip} from '@primer/react'
import {useNavigate} from '@github-ui/use-navigate'
import {securityCampaignsOrgNewCampaignPath} from '@github-ui/paths'
import type {AlertType} from '../types/security-campaign-alert'

export interface CampaignCreationButtonProps {
  organizationLogin: string
  maxCampaignsReached: boolean
  maxOpenCampaigns: number
  maxDraftCampaigns: number
  hasSpam: boolean
  setIsTemplatesDialogOpen: (isOpen: boolean) => void
  alertType?: AlertType | null
  setTemplateDialogType?: (type: AlertType) => void
}

export const CampaignCreationButton = ({
  organizationLogin,
  maxCampaignsReached,
  maxOpenCampaigns,
  maxDraftCampaigns,
  hasSpam,
  setIsTemplatesDialogOpen,
  alertType,
  setTemplateDialogType,
}: CampaignCreationButtonProps) => {
  const navigate = useNavigate()

  const onCreateFromFiltersWithAlertType = (selectedAlertType: AlertType) => {
    const type = selectedAlertType ?? alertType ?? 'code_scanning'

    setTemplateDialogType?.(type)
    const path = securityCampaignsOrgNewCampaignPath({org: organizationLogin, alertType: type})
    navigate(path, {state: {alertType: type}})
  }

  const onCreateFromTemplate = () => {
    setTemplateDialogType?.(alertType ?? 'code_scanning')
    setIsTemplatesDialogOpen(true)
  }

  const tooltipText = `Limit of ${maxOpenCampaigns} open and ${maxDraftCampaigns} draft ${
    hasSpam ? 'and spam ' : ''
  }campaigns has been reached`

  const createButton = (
    <ActionMenu.Button variant="primary" inactive={maxCampaignsReached}>
      Create campaign
    </ActionMenu.Button>
  )

  if (maxCampaignsReached) {
    return <Tooltip text={tooltipText}>{createButton}</Tooltip>
  }

  return (
    <ActionMenu>
      {createButton}
      <ActionMenu.Overlay width="small">
        <ActionList>
          <ActionList.Item onSelect={onCreateFromTemplate} disabled={maxCampaignsReached}>
            From template
          </ActionList.Item>
          <>
            {alertType !== 'secret_scanning' && (
              <ActionList.Item
                onSelect={() => onCreateFromFiltersWithAlertType('code_scanning')}
                disabled={maxCampaignsReached}
              >
                From code scanning filters
              </ActionList.Item>
            )}
            {alertType !== 'code_scanning' && (
              <ActionList.Item
                onSelect={() => onCreateFromFiltersWithAlertType('secret_scanning')}
                disabled={maxCampaignsReached}
              >
                From secret scanning filters
              </ActionList.Item>
            )}
          </>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
